input.content:
scheme: mh.ladki_bahin
base: &base {age: 35, gender: female, state: MH, marital_status: married, annual_family_income: 100000}
cases:
  - name: typical eligible woman gets Rs 1500
    date: 2024-07-01
    person: {<<: *base}
    expect: {eligible: true, monthly_inr: 1500}
    source: GR 202406281814018230 p.2 clause 2
  - name: before the GR the scheme is not in force
    date: 2024-06-27
    person: {<<: *base}
    expect: {eligible: false, in_force: false}
    source: GR 202406281814018230 p.1 clause Shasan Nirnay
  - name: on the GR date the scheme is in force
    date: 2024-06-28
    person: {<<: *base}
    expect: {eligible: true, monthly_inr: 1500}
    source: GR 202406281814018230 p.1 clause Shasan Nirnay
  - name: other scheme gives 1000, top-up is 500
    date: 2024-07-01
    person: {<<: *base, other_scheme_monthly_inr: 1000}
    expect: {eligible: true, monthly_inr: 500}
    source: GR 202406281814018230 p.2 clause 2
  - name: other scheme gives exactly 1500, eligible with zero top-up
    date: 2024-07-01
    person: {<<: *base, other_scheme_monthly_inr: 1500}
    expect: {eligible: true, monthly_inr: 0}
    source: GR 202406281814018230 p.2 clause 5(4)
  - name: other scheme gives 1501, not eligible
    date: 2024-07-01
